package com.yeyamo_mobile.api.feed_service.infrastructure.cache;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.time.Instant;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.data.redis.core.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.yeyamo_mobile.api.feed_service.application.FeedPage;
class RedisFeedCacheTests{@Test void usesVersionedKeyAndInvalidatesInConstantTime()throws Exception{StringRedisTemplate redis=mock(StringRedisTemplate.class);@SuppressWarnings("unchecked")ValueOperations<String,String>values=mock(ValueOperations.class);when(redis.opsForValue()).thenReturn(values);when(values.get("feed:version")).thenReturn("4");ObjectMapper mapper=new ObjectMapper().findAndRegisterModules();FeedPage page=new FeedPage("u1",0,20,List.of(),Instant.now());when(values.get("feed:4:u1:0:20")).thenReturn(mapper.writeValueAsString(page));RedisFeedCacheAdapter cache=new RedisFeedCacheAdapter(redis,mapper,60);assertEquals("u1",cache.get("u1",0,20).orElseThrow().userId());cache.invalidate();verify(values).increment("feed:version");}
 @Test void redisFailureFallsBackToPostgres(){StringRedisTemplate redis=mock(StringRedisTemplate.class);when(redis.opsForValue()).thenThrow(new IllegalStateException("down"));RedisFeedCacheAdapter cache=new RedisFeedCacheAdapter(redis,new ObjectMapper(),60);assertTrue(cache.get("u",0,20).isEmpty());assertDoesNotThrow(cache::invalidate);}}
